We describe the \textit{Glauber dynamics} Markov chain for sampling from $\mu_{\beta H}$ via a single step of the Markov chain.
    \begin{displayquote}
        Let $x$ be the current state.
        Pick $i\sim[N]$ uniformly at random, and transition $x'\sim\mu_{\beta H}|x_{-i}$ where $x_{-i}$ refers to $x$ with the $i$-th coordinate erased.
    \end{displayquote}

\label{lem:sl-wpi}
    Let $(\mu_t)_{0\leqslant t\leqslant T}$ be stochastic localization
    initialized at a fixed distribution $\mu$ on $\{\pm1\}^N$.
    Suppose that, with probability at least $1-\delta$, the following two events hold:
    \begin{itemize}
        \item $\sup_{0\leqslant t\leqslant T} \|\mathbf{Cov}(\mu_t)\|_{\mathrm{op}}\leqslant K$.
        \item $\mu_T$ satisfies a Poincar\'{e}~ inequality with constant $\rho_T$.
    \end{itemize}
    Then $\mu$ satisfies a $(\rho_Te^{KT},C\delta e^{KT})$-weak Poincar\'{e}~ inequality.

\label{lem:planted-contiguity}
	Let $0 \leqslant \beta < 1$. Let $\mu_{\mathsf{null}}$ be the law over measures defined by a Hamiltonian $\boldsymbol{H}_{\mathsf{null}}$ obtained by drawing $\boldsymbol{W} \sim \mathsf{GOE}(N)$ and setting $H_{\mathsf{null}}(\sigma) = \frac{\beta}{2} \cdot \sigma^\top \boldsymbol{W} \sigma$. Let $\mu_{\mathsf{pl}}$ be the law over measures defined by a Hamiltonian $\boldsymbol{H}_{\mathsf{pl}}$ obtained by drawing $\boldsymbol{W} \sim \mathsf{GOE}(N)$ and ${\boldsymbol{x}} \sim \{\pm 1\}^N$, then setting $\boldsymbol{H}_{\mathsf{pl}}(\sigma) = \frac{\beta}{2} \cdot \sigma^\top \boldsymbol{W} \sigma + \frac{\beta^2}{2N} \cdot \langle \sigma,{\boldsymbol{x}}\rangle^2$. Then, $\mu_{\mathsf{null}}$ and $\mu_{\mathsf{pl}}$ are mutually contiguous. More quantitatively, for any event $\mathcal E$ over the space of measures on $\{\pm 1\}^N$,
	\[ c \mu_{\mathsf{pl}}(\mathcal E)^2 \leqslant \mu_{\mathsf{null}}(\mathcal E) \leqslant C \sqrt{\mu_{\mathsf{pl}}(\mathcal E)} \,. \]

\label{lem:warmup-cov}
		For each row $i$, we may write
		\[ (K \mathbf{Cov} - \mathrm{Id})_{i} = \alpha^{i} \mathbf{Cov}_{i} + Y_{i} - Z_{i} \,, \]
		where $Y_{i,i} = Z_{i,i} = 0$,  $\mathbf{Cov}^{(i)} = \mathbf{Cov}^{(i)}(0)$, and
		\begin{align*}
			\alpha^i &= \beta^2 - \beta \langle \boldsymbol{W}_i , d^i \rangle \\
			Y_{i,-i} &= (d^i - \beta \mathbf{Cov}^{(i)} \boldsymbol{W}_{i})^\top \\
			Z_{i,-i} &= \beta \boldsymbol{W}_{i}^\top \left( D^i - \mathbf{Cov}^{(i)} \right) \,.
		\end{align*}

\label{cor:organized-covariance}
	For some constant $L$, for any constant $a > 0$, we have
	\[ \mathbf{Pr}\left[ \left\|\mathbf{Cov}\right\|_{\mathrm{op}} \geqslant L \right] \leqslant N^{-a} \,. \]

\label{lem:organized-off-diagonal}
		For every constant $a > 0$, there is a constant $C_a$ such that
		\[
			\mathbf{Pr}\bracks*{ \sum_{i\in[N]} \norm*{ f_i - \lambda_i \mathbf{Cov}_{-i,i} }_2^2  > C_a } \leqslant N^{-a}
		\]

\label{lem:error-bounds}
			For every constant $a > 0$, the following bounds hold for all $i\in[N]$ with probability $1-O_{\varepsilon}(N^{-a})$:
			\begin{align*}
				\left\|{ \frac{2\beta^2 m_i}{N} \parens*{ \mathbf{Cov}^{(i)}\cdot m^{(i)} - (\mathbf{Cov}\cdot m)_{-i} } }\right\|_2 &\leqslant \frac{C}{\sqrt{N}} \\
				\left\|{ \frac{\beta^3}{3}\kappa_4^{(i)}\bracks*{\boldsymbol{M}_{i,-i}^{\otimes 3}} }\right\|_2 &\leqslant \frac{C}{\sqrt{N}} \\
				\left\|{ \beta^2 m_i \kappa_3^{(i)}\bracks*{ \boldsymbol{M}_{i,-i}^{\otimes 2} - \frac{1}{N}\mathrm{Id} } }\right\|_2 &\leqslant \frac{C}{\sqrt{N}} \\
				\max_{i\in[N]}|\lambda_i|&\leqslant N^{-1/4}.
			\end{align*}

\label{lem:shifted-model-overlap-conc}
			Let $-1 \leqslant s \leqslant 1$ fixed, and $t > 0$ bounded. Consider the Ising model $\mu$ with interaction matrix $\beta\boldsymbol{M}$, for $\boldsymbol{M} = \boldsymbol{W} + \frac{\beta}{N} {\boldsymbol{x}}{\boldsymbol{x}}^\top$ (with ${\boldsymbol{x}} \sim \{\pm 1\}^{N}$), and external field
			\begin{equation}
				\label{eq:real-ext-field-law-cavity}
				\boldsymbol{h} = \left( t + \frac{s\beta^2\boldsymbol{s}}{N} \right) \cdot {\boldsymbol{x}} + \boldsymbol{g} \sqrt{t + \frac{s^2\beta^2}{N}} \,,
			\end{equation}
			with $\boldsymbol{s} \sim \{\pm 1\}$ and $\boldsymbol{g} \sim \mathcal N\left( 0 , \mathrm{Id} \right)$. Then, for some explicit deterministic constant $q$, we have
			\[ \mathbf{E} \left\langle \left| R_{12} - q \right|^{2k} \right\rangle \lesssim N^{-k} \,. \]
			The same concentration holds for overlaps of a sample with the spike ${\boldsymbol{x}}$.

\label{lem:ideal-model-overlap-conc}
			Let $\tau > 0$ bounded. Consider the Ising model $\mu$ with interaction matrix $\beta \boldsymbol{M}$ for $\boldsymbol{M} = \boldsymbol{W} + \frac{\beta}{N} {\boldsymbol{x}} {\boldsymbol{x}}^\top$ and external field
			\begin{equation}
				\label{eq:ideal-ext-field-law-cavity}
				\boldsymbol{h} = \tau {\boldsymbol{x}} + \sqrt{\tau} \boldsymbol{g} \,.
			\end{equation}
			Then, for some explicit deterministic constant $q = q(\tau)$, we have
			\[ \mathbf{E} \left\langle \left| R_{12} - q \right|^{2k} \right\rangle \lesssim N^{-k} \,. \]

