\label{lem:cov-pred-bound}
		Let $T > 0$ large. There exists a constant $\gamma = \gamma_{\beta,T}$ such that for any constant $a$ and $t \in [0,T]$,
		\begin{equation}
			\label{eq:cov-pred-bound}
			\mathbf{Pr}\left[ K_{t} \not\succeq \gamma \right] \leqslant N^{-a} \,.
		\end{equation}

For simplicity, assume that $k+\ell > 0$; the same ideas extend to the setting where $k = \ell = 0$. We write
$Y\coloneqq
\kappa_{r,s}^{(i)}
[\mathrm{Id}^{\otimes k}\otimes{\boldsymbol{x}}_{-i}^{\otimes \ell}]$. For ease of notation, set $d = r - 2k-\ell$.
We drop the cavity and shift notation, denoting by $F$ the corresponding free energy and by ${\boldsymbol{x}}$ the cavity vector ${\boldsymbol{x}}_{-i}$. Denote $n = N-1$. We now use the definition of $\kappa_r$ as an order-$r$ gradient of $F$ in order to simplify the expression for $Y$. We have, for example, that $(\kappa_3[\mathrm{Id}])_{a} = \sum_{b} \partial_{h_a} \partial_{h_b}^2 F = \partial_{h_{a}}  
  \mathord{\raisebox{-0.1ex}{ 
    \rotatebox[origin=c]{180}{$\nabla$} 
  }} 
 F$, so $\kappa_3[\mathrm{Id}] = \nabla  
  \mathord{\raisebox{-0.1ex}{ 
    \rotatebox[origin=c]{180}{$\nabla$} 
  }} 
 F$. Similarly, contracting by ${\boldsymbol{x}}$ can be expressed in terms of the gradient---for example, $(\kappa_3[{\boldsymbol{x}}])_{ab} = \sum_{c} \partial_{h_{a}} \partial_{h_{b}} \cdot {\boldsymbol{x}}_c \partial_{h_{c}} F$, so $\kappa_3[{\boldsymbol{x}}] = \nabla^2 ({\boldsymbol{x}} \cdot \nabla) F$. More generally, we have
\[ Y = \nabla^{r-2k-\ell}  
  \mathord{\raisebox{-0.1ex}{ 
    \rotatebox[origin=c]{180}{$\nabla$} 
  }} 
^{k} ({\boldsymbol{x}} \cdot \nabla)^{\ell} F \,. \]
We will start by establishing that the $k$ Laplacians and $\ell$ inner gradients will eventually result in a homogenous degree-$k+\ell$ polynomial $P$ in centered overlaps, with $Y = N^{k+\ell} \nabla^{d} \langle P\rangle$.

Suppose that $k+\ell > 0$. Let us start by understanding how a Laplacian/gradient affects the free energy. For starters, we have
\begin{align*}

  \mathord{\raisebox{-0.1ex}{ 
    \rotatebox[origin=c]{180}{$\nabla$} 
  }} 
 F &= \Tr \mathbf{Cov} = n (1 - \langle R_{12} \rangle) = \text{constant} - n \langle \overline{R}_{12} \rangle \,, \\
    ({\boldsymbol{x}} \cdot \nabla) F &= \langle {\boldsymbol{x}} , m \rangle = n \langle R_{1\star} \rangle = \text{constant} + n \langle R_{1\star} \rangle \,.
\end{align*}
Because $r \geqslant 3$, the constant terms will ultimately vanish.
Suppose that after $m$ contraction operations, we are at some polynomial $n^{m} \langle P_{m} \rangle$. A routine calculation shows that taking the Laplacian/gradient results in the Gibbs average of a polynomial of degree larger by $1$. We execute this calculation for the gradient; the calculation for the Laplacian is similar. Suppose that $P_m$ is some degree-$m$ polynomial in centered overlaps among $v$ replicas (and the plant).
\begin{align*}
    ({\boldsymbol{x}} \cdot \nabla) \langle P_{m}(\sigma^1, \ldots, \sigma^v) \rangle &= \left\langle {\boldsymbol{x}} , \left\langle P_{m} \cdot \sum_{a=1}^{v} \left( \sigma^j - \sigma^{v+1} \right) \right\rangle \right\rangle \\
        &= n \cdot \left\langle P_m \cdot \sum_{a=1}^{v} \left( R_{j\star} - R_{(v+1)\star} \right) \right\rangle \\
        &= n \cdot \left\langle P_m \cdot \sum_{a=1}^{v} \left( \overline{R}_{j\star} - \overline{R}_{(v+1)\star} \right) \right\rangle \,.
\end{align*}
This is the Gibbs average of a homogenous degree-$(m+1)$ polynomial in centered overlaps! It follows that when $k+\ell > 0$,
\[ Y = n^{k+\ell} \nabla^{r - 2k - \ell} \langle P \rangle \]
for some polynomial $P$ in centered overlaps. We may now use the same rules to expand out the gradient:
\begin{align*}
    \left(\nabla^{d} \langle P(\sigma^1,\ldots,\sigma^v) \rangle\right) = \left\langle P(\sigma^1,\ldots,\sigma^v) \cdot \bigotimes_{a=v}^{v+d-1} \left( \sum_{b=1}^{a} \left( \sigma_b - \sigma_{a+1} \right) \right) \right\rangle \,,
\end{align*}
and thus, using the replica trick to write $\langle G(\sigma)\rangle^2 = \langle G(\sigma) G(\widetilde{\sigma}) \rangle$ for a fresh replica $\widetilde{\sigma}$, we have
\begin{align*}
    \left\| Y \right\|_{\mathrm F}^2 &= n^{2(k+\ell)} \sum_{i_1,\ldots,i_d} \left\langle P(\sigma^1,\ldots,\sigma^v) \cdot \prod_{a=v}^{v+d-1} \left( \sum_{b=1}^{a} \left( \sigma_b - \sigma_{a+1} \right) \right)_{i_{a-v+1}} \right\rangle^2 \\
        &= n^{2(k+\ell)} \sum_{i_1,\ldots,i_d} \left\langle P(\sigma^1,\ldots,\sigma^v) \cdot P(\widetilde{\sigma}^1,\ldots,\widetilde{\sigma}^v) \cdot \prod_{a=v}^{v+d-1} \left( \sum_{b=1}^{a} \left( \sigma_b - \sigma_{a+1} \right) \right)_{i_{a-v+1}} \left( \sum_{b=1}^{a} \left( \widetilde{\sigma}_b - \widetilde{\sigma}_{a+1} \right) \right)_{i_{a-v+1}} \right\rangle \\
        &= n^{2(k+\ell)} \left\langle P(\sigma^1,\ldots,\sigma^v) \cdot P(\widetilde{\sigma}^1,\ldots,\widetilde{\sigma}^v) \cdot \prod_{a=v}^{v+d-1} \left\langle \sum_{b=1}^{a} \left( \sigma_b - \sigma_{a+1} \right) , \sum_{b=1}^{a} \left( \widetilde{\sigma}_b - \widetilde{\sigma}_{a+1} \right) \right\rangle \right\rangle \,.
\end{align*}
Note now that this final product term may be expressed as a degree-$d$ product of \textit{centered} replicas---this again uses the fact that the sum of the coefficients is $0$. Summarizing, we have
\[ \|Y\|_{F}^2 = n^{2(k+\ell)+d} \cdot \langle P \rangle = n^{r+\ell} \langle P \rangle \,. \]
for some homogenous degree-$2(k+\ell)+d$ polynomial $P$ in centered overlaps. Noting $2k+\ell+d = r$ and using replicas again, we have
\[ \|Y\|_{\mathrm F}^{2p} = n^{p(r+\ell)} \cdot \langle Q \rangle \]
for some homogenous degree-$p(r+\ell)$ polynomial $Q$. To complete the proof, we simply use H\"{o}lder's inequality on each term of the polynomial to reduce bounding it to bounding large moments of centered replicas---this is the content of \Cref{lem:shifted-model-overlap-conc}, which yields that $\mathbf{E}\langle Q\rangle \leqslant C n^{-p(r+\ell)/2}$, and thus that $\mathbf{E}\|Y\|_{\mathrm F}^{2p} \leqslant C N^{p(r+\ell)/2}$.

\label{fac:improved-cumulant-start}
We have
    \begin{align*}
    K^{(B)}\mathbf{Cov}^{(B)} - \mathrm{Id}
    &=\nabla r^{(B)},\\
    K^{(B)}\kappa^{(B)}_3
    &=\nabla ^2r^{(B)}-D^2T^{(B)}(m)\{\mathbf{Cov}^{(B)},\mathbf{Cov}^{(B)}\},\\
    K^{(B)}\kappa^{(B)}_4
    &=\nabla^3r^{(B)}
    -\sum_{\mathsf{Sym}} D^2T^{(B)}(m)\{\kappa^{(B)}_3,\mathbf{Cov}^{(B)}\}
    -D^3T^{(B)}(m)\{\mathbf{Cov}^{(B)},\mathbf{Cov}^{(B)},\mathbf{Cov}^{(B)}\}.
    \end{align*}

\label{lem:r-decomp}
    For $|B|\leqslant 3$ and $i\in[N]\setminus B$, we have $r_i^{(B)} = \zeta_i^{(B)} + m_i^{(B)} \lambda_i^{(B)}$, where
    \begin{equation}\label{eq:zeta}
        \zeta_i^{(B)}
        = \frac{\phi_i^{(B)}(1) - \phi_i^{(B)}(-1) - (\phi_i^{(B)})'(1) - (\phi_i^{(B)})'(-1)}{2}
        = -\frac14 \int_{-1}^1 (1-s^2) (\phi_i^{(B)})^{(3)}(s) \mathop{}\!\mathrm{d} s
    \end{equation}
